changeSet.sql:
UPDATE notification_profile profile
SET user_keycloak_id = app_user.keycloak_id FROM app_user
WHERE app_user.id = profile.user_id;

changeSet.rollback:
DELETE FROM notification_profile WHERE user_id IS NULL;
DROP INDEX uq_notification_profile_active_subject;
CREATE UNIQUE INDEX uq_notification_profile_active_user
ON notification_profile(user_id) WHERE deleted = FALSE;
ALTER TABLE notification_profile ALTER COLUMN user_id SET NOT NULL;
ALTER TABLE notification_profile DROP COLUMN user_keycloak_id;
